/**
 * Curio Backend — Server-Sent Events (SSE) Protocol Utilities
 *
 * Implements standard, robust Server-Sent Events streaming over HTTP POST
 * according to W3C EventSource / SSE specifications:
 *
 * Events:
 *   - 'start': Initial metadata, requestId, selected provider
 *   - 'delta': Incremental text chunk generated by LLM
 *   - 'done':  Stream completion with token usage metadata
 *   - 'error': Standardized error structure with retry flags
 *
 * @module backend/utils/sse
 */

/**
 * Initialize HTTP response headers for Server-Sent Events streaming.
 * @param {import('express').Response} res
 */
export function initSSE(res) {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache, no-transform',
    Connection: 'keep-alive',
    'X-Accel-Buffering': 'no', // Disable proxy buffering (Nginx, Cloudflare)
  });
  if (typeof res.flushHeaders === 'function') {
    res.flushHeaders();
  }
}

/**
 * Format an SSE event into standard wire format:
 * event: <eventName>\n
 * data: <jsonString>\n\n
 *
 * Handles multiline data correctly by formatting each line with `data: `.
 *
 * @param {string} event
 * @param {any} data
 * @returns {string}
 */
export function formatSSEEvent(event, data) {
  const jsonStr = typeof data === 'string' ? data : JSON.stringify(data);
  const lines = jsonStr.split('\n');
  const dataBlock = lines.map((line) => `data: ${line}`).join('\n');
  return `event: ${event}\n${dataBlock}\n\n`;
}

/**
 * Safely send an SSE event to an Express response.
 * Guards against writing after response has finished or client has disconnected.
 *
 * @param {import('express').Response} res
 * @param {string} event
 * @param {any} data
 * @returns {boolean} Whether the write succeeded
 */
export function sendSSE(res, event, data) {
  if (res.writableEnded || res.destroyed || !res.writable) {
    return false;
  }
  try {
    res.write(formatSSEEvent(event, data));
    if (typeof res.flush === 'function') {
      res.flush();
    }
    return true;
  } catch (_e) {
    return false;
  }
}

/**
 * Send 'start' event.
 * @param {import('express').Response} res
 * @param {{ requestId: string, provider: string, model?: string }} payload
 */
export function sendStart(res, payload) {
  return sendSSE(res, 'start', {
    requestId: payload.requestId,
    provider: payload.provider,
    model: payload.model || null,
    timestamp: Date.now(),
  });
}

/**
 * Send 'delta' incremental text event.
 * @param {import('express').Response} res
 * @param {string} text
 */
export function sendDelta(res, text) {
  if (!text) return true;
  return sendSSE(res, 'delta', {
    text,
  });
}

/**
 * Send 'done' completion event and end response stream.
 * @param {import('express').Response} res
 * @param {{ requestId: string, provider: string, model?: string, usage?: Object }} payload
 */
export function sendDone(res, payload) {
  const sent = sendSSE(res, 'done', {
    requestId: payload.requestId,
    provider: payload.provider,
    model: payload.model || null,
    usage: payload.usage || null,
    timestamp: Date.now(),
  });
  if (!res.writableEnded) {
    res.end();
  }
  return sent;
}

/**
 * Send 'error' event and end response stream.
 * @param {import('express').Response} res
 * @param {{ code: string, message: string, retryable?: boolean }} payload
 */
export function sendError(res, payload) {
  const sent = sendSSE(res, 'error', {
    code: payload.code || 'INTERNAL_ERROR',
    message: payload.message || 'An error occurred during explanation generation.',
    retryable: Boolean(payload.retryable),
    timestamp: Date.now(),
  });
  if (!res.writableEnded) {
    res.end();
  }
  return sent;
}

/**
 * Asynchronously parse an upstream SSE stream from a fetch ReadableStream.
 * Correctly buffers across arbitrary network chunk boundaries and splits on "\n\n".
 *
 * @param {ReadableStream<Uint8Array>} bodyStream
 * @param {(event: { event: string, data: any, rawData: string }) => void} onEvent
 * @param {AbortSignal} [signal]
 */
export async function parseSSEStream(bodyStream, onEvent, signal) {
  const reader = bodyStream.getReader();
  const decoder = new TextDecoder('utf-8');
  let buffer = '';

  try {
    while (true) {
      if (signal?.aborted) {
        await reader.cancel();
        break;
      }

      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });

      // Split events by double newline
      const parts = buffer.split(/\r?\n\r?\n/);
      // The last part is incomplete, hold it in buffer
      buffer = parts.pop() || '';

      for (const part of parts) {
        const trimmed = part.trim();
        if (!trimmed) continue;

        let eventName = 'message';
        const dataLines = [];

        const lines = trimmed.split(/\r?\n/);
        for (const line of lines) {
          if (line.startsWith('event:')) {
            eventName = line.substring(6).trim();
          } else if (line.startsWith('data:')) {
            dataLines.push(line.substring(5).trimStart());
          }
        }

        if (dataLines.length > 0) {
          const rawData = dataLines.join('\n');
          let parsedData = rawData;
          if (rawData !== '[DONE]') {
            try {
              parsedData = JSON.parse(rawData);
            } catch (_e) {
              parsedData = rawData;
            }
          }
          onEvent({ event: eventName, data: parsedData, rawData });
        }
      }
    }

    // Flush any remaining buffered message
    if (buffer.trim()) {
      const lines = buffer.trim().split(/\r?\n/);
      let eventName = 'message';
      const dataLines = [];
      for (const line of lines) {
        if (line.startsWith('event:')) {
          eventName = line.substring(6).trim();
        } else if (line.startsWith('data:')) {
          dataLines.push(line.substring(5).trimStart());
        }
      }
      if (dataLines.length > 0) {
        const rawData = dataLines.join('\n');
        let parsedData = rawData;
        try {
          parsedData = JSON.parse(rawData);
        } catch (_e) {
          parsedData = rawData;
        }
        onEvent({ event: eventName, data: parsedData, rawData });
      }
    }
  } finally {
    reader.releaseLock();
  }
}

